# Sphinx configuration for the hypso package documentation.
#
# Build (from the repository root):
#     pip install -r docs/requirements.txt
#     sphinx-build -W --keep-going -b html docs docs/_build/html
#
# The API reference is generated by sphinx-autoapi from the source in
# hypso/hypso without importing it, so the build does not need the package's
# own dependencies.
import subprocess

# -- Project information -----------------------------------------------------

project = "hypso"
copyright = "Norwegian University of Science and Technology (NTNU)"
author = "Cameron Penne"


def _git_version() -> str:
    # The package version is the git tag (docs/versioning.rst); importing
    # hypso to ask it would need all of its dependencies.
    try:
        return subprocess.run(["git", "describe", "--tags", "--always"], capture_output=True, text=True,
                              check=True).stdout.strip().lstrip("v")
    except (OSError, subprocess.CalledProcessError):
        return "unknown"


release = _git_version()
version = release.split("-")[0]

# -- General configuration ---------------------------------------------------

extensions = [
    "sphinx.ext.napoleon",        # NumPy-style docstrings
    "sphinx.ext.intersphinx",
    "sphinx.ext.viewcode",
    "autoapi.extension",
]
exclude_patterns = ["_build"]
nitpicky = False

napoleon_google_docstring = False
napoleon_numpy_docstring = True

intersphinx_mapping = {
    "python": ("https://docs.python.org/3", None),
    "numpy": ("https://numpy.org/doc/stable/", None),
    "xarray": ("https://docs.xarray.dev/en/stable/", None),
    "pyresample": ("https://pyresample.readthedocs.io/en/stable/", None),
}

# -- API reference (sphinx-autoapi) ------------------------------------------

autoapi_type = "python"
autoapi_dirs = ["../hypso/hypso"]
autoapi_root = "api"
autoapi_add_toctree_entry = False       # linked from index.rst
autoapi_options = ["members", "show-inheritance", "show-module-summary", "imported-members"]
autoapi_member_order = "groupwise"
autoapi_python_class_content = "both"
# Internal code: subprocess drivers run inside the AC tools' own processes,
# and the Satpy plugin is registered by entry point, not imported by users.
autoapi_ignore = ["*/ac/adapters/_*_driver.py", "*/satpy/*", "*/__pycache__/*"]
autodoc_typehints = "description"
suppress_warnings = ["autoapi.python_import_resolution"]

# -- HTML output -------------------------------------------------------------

html_theme = "pydata_sphinx_theme"
html_title = f"hypso {release}"
html_theme_options = {
    "github_url": "https://github.com/NTNU-SmallSat-Lab/hypso-package",
    "navigation_with_keys": False,
    "show_toc_level": 2,
}
